# >>> CHOICES
_choice_output() {
    printf '%s\t%s\n' \
        json 'JSON output' \
        yaml 'YAML output' \
        cbor 'CBOR output'
}

_choice_types() {
    tokei --languages | gawk '
        /^┃/ {
            line = $0
            sub(/^┃[[:space:]]*/, "", line)
            sub(/[[:space:]]*┃[[:space:]]*$/, "", line)
            if (line ~ /^━/ || line ~ /^Language[[:space:]]/) {
                next
            }
            if (match(line, /[[:space:]][[:space:]]+/)) {
                name = substr(line, 1, RSTART - 1)
                exts = substr(line, RSTART + RLENGTH)
                sub(/[[:space:]]+$/, "", exts)
                if (name != "") {
                    print name "\t" exts
                }
            }
        }'
}
